<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="description" content="Dune Line — the overnight sleeper that crosses six hundred kilometres of starlit desert and arrives in a city made of neon.">
<meta name="theme-color" content="#0f0b22">
<title>Dune Line — Fall asleep in the dunes. Wake up in neon.</title>
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='7' fill='%230f0b22'/%3E%3Cpath d='M4 21 Q11 12 18 18 T28 16' stroke='%23ffb454' stroke-width='2.4' fill='none' stroke-linecap='round'/%3E%3Ccircle cx='24' cy='8' r='2.4' fill='%233ae8ff'/%3E%3C/svg%3E">
<script>document.documentElement.classList.add('js');</script>
<style>
/* ============================================================
   DUNE LINE — design tokens
   ============================================================ */
:root{
  --bg:        #0f0b22;
  --bg-2:      #120d2a;
  --panel:     #181236;
  --panel-2:   #1d1540;
  --line:      rgba(230,220,255,.09);
  --line-2:    rgba(230,220,255,.17);
  --text:      #f2edff;
  --muted:     #b9aed6;
  --faint:     #8d80b0;
  --amber:     #ffb454;
  --amber-hi:  #ffc46b;
  --pink:      #ff4fa3;
  --cyan:      #3ae8ff;
  --cream:     #f5e9d6;
  --serif: Georgia, "Iowan Old Style", "Times New Roman", serif;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", "Segoe UI Mono", Menlo, Consolas, monospace;
  --journey: linear-gradient(100deg, var(--amber-hi), var(--pink) 55%, var(--cyan));
  --nav-h: 72px;
  --radius: 18px;
}

/* ============================================================
   Reset & base
   ============================================================ */
*,*::before,*::after{ box-sizing:border-box; margin:0; padding:0; }
html{ scroll-padding-top: 96px; }
@media (prefers-reduced-motion: no-preference){ html{ scroll-behavior:smooth; } }
body{
  background: var(--bg);
  color: var(--text);
  font: 16px/1.65 var(--sans);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
::selection{ background: var(--amber); color:#241028; }
img,svg{ display:block; }
a{ color:inherit; text-decoration:none; }
button{ font:inherit; color:inherit; background:none; border:0; cursor:pointer; }
ul{ list-style:none; }
:focus-visible{ outline:2px solid var(--amber); outline-offset:3px; border-radius:4px; }
::-webkit-scrollbar{ width:10px; }
::-webkit-scrollbar-track{ background:var(--bg-2); }
::-webkit-scrollbar-thumb{ background:#2c2350; border-radius:8px; border:2px solid var(--bg-2); }
::-webkit-scrollbar-thumb:hover{ background:#3d3170; }

.container{ width:min(1200px, 100% - 48px); margin-inline:auto; }
.mono{ font-family:var(--mono); }
.skip-link{
  position:fixed; top:-60px; left:16px; z-index:400;
  background:var(--amber); color:#241028; font-weight:600;
  padding:10px 18px; border-radius:8px; transition:top .2s ease;
}
.skip-link:focus{ top:14px; }

/* Film grain — pure inline SVG, no assets */
.grain{
  position:fixed; inset:0; width:100%; height:100%;
  z-index:180; pointer-events:none; opacity:.05; mix-blend-mode:overlay;
}

/* ============================================================
   Type helpers
   ============================================================ */
.eyebrow{
  font: 600 11px/1 var(--mono);
  letter-spacing:.24em; text-transform:uppercase; color:var(--amber);
  display:flex; align-items:center; gap:12px;
}
.eyebrow::before{ content:""; width:26px; height:1px; background:var(--amber); opacity:.7; }
.eyebrow .idx{ color:var(--faint); }
.h2{
  font: 400 clamp(30px, 3.5vw, 44px)/1.12 var(--serif);
  letter-spacing:-.01em; margin-top:18px;
}
.h2 em{ font-style:italic; color:var(--cream); }
.grad{
  font-style:italic;
  background:var(--journey);
  -webkit-background-clip:text; background-clip:text;
  color:transparent;
  padding-right:.08em; margin-right:-.08em;
}
.section{ padding:112px 0; position:relative; }
.section-head{
  display:flex; align-items:flex-end; justify-content:space-between;
  gap:48px; margin-bottom:56px;
}
.section-head .lede{ max-width:380px; color:var(--muted); font-size:15.5px; padding-bottom:6px; }

/* ============================================================
   Buttons
   ============================================================ */
.btn{
  display:inline-flex; align-items:center; justify-content:center; gap:10px;
  padding:14px 26px; border-radius:999px;
  font:600 15px/1 var(--sans); letter-spacing:.01em;
  transition:transform .22s cubic-bezier(.2,.7,.2,1), box-shadow .22s ease, background .22s ease, border-color .22s ease, color .22s ease;
  white-space:nowrap;
}
.btn svg{ transition:transform .22s ease; }
.btn:hover svg{ transform:translateX(3px); }
.btn-primary{
  background:linear-gradient(135deg, #ffc46b, #ff9a4d);
  color:#241028;
  box-shadow:0 8px 26px rgba(255,160,70,.24), inset 0 1px 0 rgba(255,255,255,.35);
}
.btn-primary:hover{ transform:translateY(-2px); box-shadow:0 14px 34px rgba(255,160,70,.34), inset 0 1px 0 rgba(255,255,255,.35); }
.btn-primary:active{ transform:translateY(0); }
.btn-ghost{
  border:1px solid var(--line-2); color:var(--text); background:rgba(255,255,255,.02);
}
.btn-ghost:hover{ border-color:rgba(255,180,84,.6); color:var(--amber-hi); background:rgba(255,180,84,.06); transform:translateY(-2px); }
.btn-block{ width:100%; }

/* ============================================================
   Navigation
   ============================================================ */
.site-header{
  position:fixed; top:0; left:0; right:0; z-index:200;
  height:var(--nav-h);
  transition:background .3s ease, border-color .3s ease, box-shadow .3s ease;
  border-bottom:1px solid transparent;
}
.site-header.scrolled{
  background:rgba(15,11,34,.82);
  -webkit-backdrop-filter:blur(14px); backdrop-filter:blur(14px);
  border-bottom-color:var(--line);
  box-shadow:0 12px 40px rgba(5,3,16,.45);
}
.nav-inner{ height:var(--nav-h); display:flex; align-items:center; gap:32px; }
.brand{ display:flex; align-items:center; gap:11px; }
.brand-name{ font:400 21px/1 var(--serif); letter-spacing:.01em; }
.brand-name em{ font-style:italic; color:var(--amber); }
.nav-links{ display:flex; gap:30px; margin-left:auto; }
.nav-links a{
  position:relative; font:500 13.5px/1 var(--sans); color:var(--muted);
  padding:8px 2px; transition:color .2s ease;
}
.nav-links a::after{
  content:""; position:absolute; left:0; right:0; bottom:0; height:2px; border-radius:2px;
  background:linear-gradient(90deg, var(--amber), var(--pink));
  transform:scaleX(0); transform-origin:left; transition:transform .25s ease;
}
.nav-links a:hover, .nav-links a.active{ color:var(--text); }
.nav-links a:hover::after, .nav-links a.active::after{ transform:scaleX(1); }
.nav-actions{ display:flex; align-items:center; gap:16px; }
.nav-chip{
  font:600 10.5px/1 var(--mono); letter-spacing:.14em; color:var(--cyan);
  border:1px solid rgba(58,232,255,.3); background:rgba(58,232,255,.06);
  padding:8px 12px; border-radius:999px; display:flex; align-items:center; gap:8px;
}
.nav-chip .dot{ width:6px; height:6px; border-radius:50%; background:var(--cyan); animation:blink 2.2s steps(1) infinite; }
.nav-cta{ padding:11px 20px; font-size:13.5px; }
.menu-btn{ display:none; width:42px; height:42px; border:1px solid var(--line-2); border-radius:10px; position:relative; }
.menu-btn span{
  position:absolute; left:11px; right:11px; height:2px; border-radius:2px; background:var(--text);
  transition:transform .25s ease, top .25s ease;
}
.menu-btn span:nth-child(1){ top:16px; } .menu-btn span:nth-child(2){ top:24px; }
body.menu-open .menu-btn span:nth-child(1){ top:20px; transform:rotate(45deg); }
body.menu-open .menu-btn span:nth-child(2){ top:20px; transform:rotate(-45deg); }
.mobile-menu{
  display:none; position:absolute; top:var(--nav-h); left:0; right:0;
  background:rgba(18,13,42,.97); -webkit-backdrop-filter:blur(14px); backdrop-filter:blur(14px);
  border-bottom:1px solid var(--line);
  max-height:0; overflow:hidden; transition:max-height .35s ease;
}
body.menu-open .mobile-menu{ max-height:360px; }
.mobile-menu ul{ padding:14px 24px 22px; display:grid; gap:4px; }
.mobile-menu a{ display:block; padding:12px 4px; font:500 16px/1 var(--sans); color:var(--muted); border-bottom:1px solid var(--line); }
.mobile-menu a:hover{ color:var(--amber-hi); }
.mobile-menu .btn{ margin-top:14px; }

/* ============================================================
   Hero
   ============================================================ */
.hero{
  position:relative; min-height:760px; overflow:hidden;
  padding:calc(var(--nav-h) + 76px) 0 34px;
  display:flex; flex-direction:column;
}
.scene{ position:absolute; inset:0; width:100%; height:100%; }
.hero::before{ /* legibility vignette */
  content:""; position:absolute; inset:0; z-index:1; pointer-events:none;
  background:linear-gradient(100deg, rgba(11,8,29,.9) 0%, rgba(11,8,29,.55) 34%, rgba(11,8,29,0) 62%);
}
.hero::after{ /* seamless blend into page */
  content:""; position:absolute; left:0; right:0; bottom:0; height:150px; z-index:1; pointer-events:none;
  background:linear-gradient(180deg, rgba(15,11,34,0), var(--bg));
}
.hero .container{ position:relative; z-index:2; display:flex; flex-direction:column; flex:1; }
.hero-copy{ max-width:660px; text-shadow:0 2px 26px rgba(10,8,28,.55); }
.hero-eyebrow{
  font:600 11px/1.6 var(--mono); letter-spacing:.22em; color:var(--amber);
  display:inline-flex; align-items:center; gap:10px; text-transform:uppercase;
}
.hero-eyebrow .sep{ color:var(--faint); }
.hero h1{
  font:400 clamp(44px, 6.2vw, 80px)/1.05 var(--serif);
  letter-spacing:-.015em; margin:20px 0 22px;
}
.hero h1 .glow{ filter:drop-shadow(0 0 20px rgba(255,79,163,.35)); }
.hero-sub{ font-size:17px; line-height:1.7; color:var(--muted); max-width:530px; }
.hero-ctas{ display:flex; flex-wrap:wrap; gap:14px; margin-top:32px; }
.hero-meta{ display:flex; flex-wrap:wrap; gap:10px 26px; margin-top:28px; }
.hero-meta span{
  display:inline-flex; align-items:center; gap:8px;
  font:500 11px/1 var(--mono); letter-spacing:.12em; color:var(--faint); text-transform:uppercase;
}
.hero-meta svg{ flex:none; }

/* Tonight's service strip */
.route-strip{
  margin-top:auto; padding-top:52px;
}
.route-strip-inner{
  display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:36px;
  background:rgba(18,13,42,.72);
  -webkit-backdrop-filter:blur(10px); backdrop-filter:blur(10px);
  border:1px solid var(--line-2); border-radius:16px;
  padding:18px 26px;
  box-shadow:0 20px 50px rgba(5,3,16,.4);
}
.rs-label{ font:600 10px/1 var(--mono); letter-spacing:.2em; color:var(--faint); text-transform:uppercase; margin-bottom:7px; }
.rs-value{ font:400 17px/1.2 var(--serif); font-style:italic; color:var(--cream); }
.rs-sub{ font:500 10.5px/1 var(--mono); letter-spacing:.14em; color:var(--faint); margin-top:7px; }
.rs-route{ display:flex; align-items:center; gap:14px; min-width:0; }
.rs-route svg{ flex:none; }
.rs-line{ position:relative; flex:1; height:2px; background:repeating-linear-gradient(90deg, var(--line-2) 0 7px, transparent 7px 13px); border-radius:2px; }
.rs-dot{
  position:absolute; top:50%; left:0; width:9px; height:9px; margin-top:-4.5px; border-radius:50%;
  background:var(--amber); box-shadow:0 0 12px 2px rgba(255,180,84,.7);
  animation:routedot 16s linear infinite;
}
.rs-times{ display:flex; justify-content:space-between; font:600 11px/1 var(--mono); letter-spacing:.1em; color:var(--muted); margin-top:10px; }
.rs-times b{ color:var(--text); font-weight:600; }
.rs-count{ text-align:right; }
.rs-count .rs-value{ font:600 26px/1 var(--mono); font-style:normal; color:var(--cyan); font-variant-numeric:tabular-nums; letter-spacing:.04em; }

/* ============================================================
   Ticker
   ============================================================ */
.ticker{
  border-block:1px solid rgba(255,180,84,.16);
  background:var(--bg-2); overflow:hidden; padding:13px 0;
}
.ticker-track{ display:flex; width:max-content; animation:tickmove 42s linear infinite; }
.ticker:hover .ticker-track{ animation-play-state:paused; }
.ticker-group{
  display:flex; align-items:center; white-space:nowrap;
  font:600 11px/1 var(--mono); letter-spacing:.22em; color:rgba(255,196,107,.75); text-transform:uppercase;
}
.ticker-group span{ padding:0 22px; }
.ticker-group i{ font-style:normal; color:var(--pink); font-size:9px; }

/* ============================================================
   Features
   ============================================================ */
#experience{ background:
  radial-gradient(700px 420px at 8% 0%, rgba(255,180,84,.05), transparent 65%),
  radial-gradient(700px 460px at 96% 100%, rgba(58,232,255,.045), transparent 65%);
}
.f-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:24px; }
.f-card{
  height:100%; display:flex; flex-direction:column;
  background:linear-gradient(180deg, var(--panel), #151030);
  border:1px solid var(--line); border-radius:var(--radius);
  padding:30px 28px 26px;
  transition:transform .3s cubic-bezier(.2,.7,.2,1), border-color .3s ease, box-shadow .3s ease;
}
.f-card:hover{ transform:translateY(-5px); box-shadow:0 24px 50px rgba(5,3,16,.45); }
.f-card.acc-amber:hover{ border-color:rgba(255,180,84,.45); }
.f-card.acc-pink:hover{ border-color:rgba(255,79,163,.45); }
.f-card.acc-cyan:hover{ border-color:rgba(58,232,255,.45); }
.f-top{ display:flex; align-items:flex-start; justify-content:space-between; margin-bottom:24px; }
.f-icon{
  width:64px; height:64px; border-radius:16px; display:grid; place-items:center;
  border:1px solid var(--line); transition:box-shadow .3s ease;
}
.acc-amber .f-icon{ background:rgba(255,180,84,.07); } .acc-amber:hover .f-icon{ box-shadow:0 0 26px rgba(255,180,84,.22); }
.acc-pink  .f-icon{ background:rgba(255,79,163,.07); } .acc-pink:hover  .f-icon{ box-shadow:0 0 26px rgba(255,79,163,.22); }
.acc-cyan  .f-icon{ background:rgba(58,232,255,.07); } .acc-cyan:hover  .f-icon{ box-shadow:0 0 26px rgba(58,232,255,.22); }
.f-idx{ font:600 12px/1 var(--mono); letter-spacing:.18em; color:var(--faint); padding-top:6px; }
.f-card h3{ font:400 25px/1.2 var(--serif); margin-bottom:12px; }
.f-card p{ font-size:14.5px; line-height:1.7; color:var(--muted); flex:1; }
.f-foot{
  margin-top:24px; padding-top:16px; border-top:1px dashed var(--line-2);
  font:600 10.5px/1.5 var(--mono); letter-spacing:.16em; text-transform:uppercase;
}
.acc-amber .f-foot{ color:var(--amber); } .acc-pink .f-foot{ color:var(--pink); } .acc-cyan .f-foot{ color:var(--cyan); }

/* ============================================================
   Timetable
   ============================================================ */
.board{
  background:var(--bg-2); border:1px solid var(--line-2); border-radius:20px;
  overflow:hidden; box-shadow:0 30px 70px rgba(5,3,16,.45);
}
.board-bar{
  display:flex; align-items:center; justify-content:space-between; gap:20px; flex-wrap:wrap;
  padding:18px 26px; border-bottom:1px solid var(--line);
  background:rgba(255,255,255,.02);
}
.board-title{ font:600 11px/1.6 var(--mono); letter-spacing:.2em; color:var(--amber); text-transform:uppercase; }
.board-title small{ display:block; color:var(--faint); letter-spacing:.16em; font-weight:500; }
.board-clock{ display:flex; align-items:center; gap:10px; font:600 15px/1 var(--mono); color:var(--cyan); font-variant-numeric:tabular-nums; letter-spacing:.06em; }
.board-clock .dot{ width:7px; height:7px; border-radius:50%; background:var(--cyan); box-shadow:0 0 10px rgba(58,232,255,.8); animation:blink 1.6s steps(1) infinite; }
.board-clock small{ font-size:9.5px; letter-spacing:.2em; color:var(--faint); }
.board-cols, .t-row{
  display:grid; grid-template-columns:88px 88px minmax(0,1fr) 92px 150px 122px;
  gap:18px; align-items:center; padding:16px 26px;
}
.board-cols{
  font:600 9.5px/1 var(--mono); letter-spacing:.22em; color:var(--faint); text-transform:uppercase;
  border-bottom:1px solid var(--line); background:rgba(255,255,255,.015); padding-block:12px;
}
.t-row{ border-bottom:1px solid var(--line); transition:background .2s ease; padding-block:21px; }
.t-row:last-of-type{ border-bottom:0; }
.t-row:hover{ background:rgba(255,180,84,.045); }
.t-time{ font:600 21px/1 var(--mono); font-variant-numeric:tabular-nums; letter-spacing:.02em; }
.t-time sup{ font-size:10px; color:var(--amber); margin-left:3px; font-weight:600; }
.t-svc-name{ font:400 18px/1.25 var(--serif); font-style:italic; color:var(--cream); }
.t-svc-tags{ font:500 10px/1.6 var(--mono); letter-spacing:.16em; color:var(--faint); text-transform:uppercase; margin-top:5px; }
.t-svc-tags .dur-m{ display:none; }
.t-dur{ font:500 12.5px/1 var(--mono); letter-spacing:.1em; color:var(--muted); }
.pill{
  display:inline-flex; align-items:center; gap:8px;
  font:600 10px/1 var(--mono); letter-spacing:.16em; text-transform:uppercase;
  padding:7px 12px; border-radius:999px; border:1px solid; white-space:nowrap;
}
.pill .dot{ width:6px; height:6px; border-radius:50%; background:currentColor; position:relative; }
.pill-cyan{ color:var(--cyan); border-color:rgba(58,232,255,.35); background:rgba(58,232,255,.07); }
.pill-amber{ color:var(--amber); border-color:rgba(255,180,84,.4); background:rgba(255,180,84,.08); }
.pill-pink{ color:var(--pink); border-color:rgba(255,79,163,.4); background:rgba(255,79,163,.08); }
.pill-amber .dot::after{
  content:""; position:absolute; inset:-4px; border-radius:50%; border:1px solid currentColor;
  animation:ping 1.8s ease-out infinite;
}
.t-fare{ text-align:right; }
.t-from{ font:600 13px/1 var(--mono); color:var(--text); }
.t-from small{ color:var(--faint); font-weight:500; font-size:10px; letter-spacing:.1em; }
.t-book{
  display:inline-flex; align-items:center; gap:5px; margin-top:7px;
  font:600 11px/1 var(--mono); letter-spacing:.14em; color:var(--amber); text-transform:uppercase;
}
.t-book svg{ transition:transform .2s ease; }
.t-book:hover svg{ transform:translateX(3px); }
.board-note{
  display:flex; justify-content:space-between; gap:16px; flex-wrap:wrap;
  padding:14px 26px; border-top:1px solid var(--line);
  font:500 9.5px/1.7 var(--mono); letter-spacing:.16em; color:var(--faint); text-transform:uppercase;
}

/* ============================================================
   Fares
   ============================================================ */
#fares{ background:
  radial-gradient(760px 480px at 50% 20%, rgba(255,79,163,.05), transparent 65%);
}
.fare-head-right{ display:flex; flex-direction:column; align-items:flex-end; gap:10px; padding-bottom:4px; }
.seg{
  display:inline-flex; padding:4px; gap:4px; border:1px solid var(--line-2); border-radius:999px;
  background:var(--bg-2);
}
.seg-btn{
  padding:9px 20px; border-radius:999px; font:600 12.5px/1 var(--sans); color:var(--muted);
  transition:background .2s ease, color .2s ease;
}
.seg-btn.active{ background:linear-gradient(135deg,#ffc46b,#ff9a4d); color:#241028; }
.seg-hint{ font:600 9.5px/1 var(--mono); letter-spacing:.2em; color:var(--faint); text-transform:uppercase; }
.fare-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:26px; align-items:stretch; }
.fare-wrap.featured{ margin-top:-16px; }
.fare-ring{
  height:100%; border-radius:20px; padding:1.5px;
  background:linear-gradient(165deg, var(--amber-hi), var(--pink) 52%, var(--cyan));
  box-shadow:0 24px 60px rgba(255,79,163,.16);
  position:relative;
}
.fare-badge{
  position:absolute; top:-13px; left:50%; transform:translateX(-50%); z-index:2;
  font:700 9.5px/1 var(--mono); letter-spacing:.22em; color:#241028; text-transform:uppercase;
  background:linear-gradient(90deg,#ffc46b,#ff7ab0); padding:7px 14px; border-radius:999px;
  box-shadow:0 6px 18px rgba(255,120,140,.35); white-space:nowrap;
}
.fare-card{
  height:100%; display:flex; flex-direction:column;
  background:linear-gradient(180deg, #191238, #151030);
  border:1px solid var(--line); border-radius:var(--radius);
  padding:28px 28px 26px; position:relative;
  transition:transform .3s cubic-bezier(.2,.7,.2,1), border-color .3s ease, box-shadow .3s ease;
}
.fare-ring .fare-card{ border:0; border-radius:18.5px; background:linear-gradient(180deg,#1c1442,#171136); }
.fare-wrap:not(.featured) .fare-card:hover{ transform:translateY(-5px); border-color:var(--line-2); box-shadow:0 24px 50px rgba(5,3,16,.45); }
.fare-top{ display:flex; align-items:center; justify-content:space-between; margin-bottom:20px; }
.fare-name{ font:700 11px/1 var(--mono); letter-spacing:.24em; text-transform:uppercase; }
.f-amber{ color:var(--amber); } .f-pink{ color:var(--pink); } .f-cyan{ color:var(--cyan); }
.fare-route{ font:500 10px/1 var(--mono); letter-spacing:.14em; color:var(--faint); }
.fare-price{ display:flex; align-items:baseline; gap:6px; }
.fare-price .cur{ font:400 22px/1 var(--serif); color:var(--amber); align-self:flex-start; padding-top:8px; }
.price-num{ font:400 56px/1 var(--serif); letter-spacing:-.02em; font-variant-numeric:lining-nums; }
.fare-price .per{ font-size:13px; color:var(--faint); }
.price-note{ font:600 9.5px/1 var(--mono); letter-spacing:.2em; color:var(--faint); text-transform:uppercase; margin-top:10px; }
.bump{ animation:bump .38s cubic-bezier(.2,.7,.2,1); }
.perf{ position:relative; border-top:1.5px dashed var(--line-2); margin:24px -28px 20px; }
.perf::before,.perf::after{
  content:""; position:absolute; top:-9px; width:16px; height:16px; border-radius:50%;
  background:var(--bg); border:1px solid var(--line);
}
.perf::before{ left:-9px; } .perf::after{ right:-9px; }
.fare-list{ display:grid; gap:11px; flex:1; }
.fare-list li{ display:flex; gap:11px; align-items:flex-start; font-size:14px; line-height:1.5; color:var(--muted); }
.fare-list svg{ flex:none; margin-top:3px; }
.fare-cta{ margin-top:26px; }
.barcode{ display:flex; align-items:stretch; height:30px; margin-top:22px; color:rgba(240,234,255,.7); overflow:hidden; }
.barcode i{ background:currentColor; height:100%; flex:none; }
.fare-code{ font:500 9px/1 var(--mono); letter-spacing:.3em; color:var(--faint); margin-top:9px; text-transform:uppercase; }

/* ============================================================
   Testimonial
   ============================================================ */
#passengers{ padding-top:96px; }
.quote-wrap{ max-width:840px; margin-inline:auto; text-align:center; position:relative; }
.quote-mark{
  position:absolute; top:-46px; left:-14px; z-index:0; opacity:.9; pointer-events:none;
}
.quote-stars{ display:flex; justify-content:center; gap:5px; margin-bottom:16px; }
.quote-rating{ font:600 10.5px/1 var(--mono); letter-spacing:.22em; color:var(--faint); text-transform:uppercase; margin-bottom:34px; }
blockquote{
  position:relative; z-index:1;
  font:400 clamp(23px, 2.6vw, 32px)/1.45 var(--serif); letter-spacing:-.005em; color:var(--cream);
}
blockquote .hl{
  font-style:italic;
  background:linear-gradient(90deg, var(--pink), var(--cyan)) left bottom / 100% 2px no-repeat;
  padding-bottom:3px;
}
.quote-who{
  display:flex; align-items:center; justify-content:center; gap:16px; margin-top:38px; flex-wrap:wrap;
}
.quote-who .avatar{ flex:none; }
.quote-id{ text-align:left; }
.quote-id b{ display:block; font:600 15px/1.3 var(--sans); }
.quote-id span{ font:500 10px/1.6 var(--mono); letter-spacing:.18em; color:var(--faint); text-transform:uppercase; }
.quote-stub{
  font:600 9.5px/1.6 var(--mono); letter-spacing:.18em; color:var(--cyan); text-transform:uppercase;
  border:1px dashed rgba(58,232,255,.4); border-radius:8px; padding:9px 14px; margin-left:10px;
  background:rgba(58,232,255,.05);
}

/* ============================================================
   Footer
   ============================================================ */
.site-footer{ border-top:1px solid var(--line); background:linear-gradient(180deg, var(--bg-2), #0c081c); }
.footer-cta{
  display:flex; align-items:center; justify-content:space-between; gap:40px;
  padding:72px 0 64px; border-bottom:1px solid var(--line);
}
.footer-cta h2{ font:400 clamp(28px,3.2vw,40px)/1.2 var(--serif); letter-spacing:-.01em; }
.footer-cta-right{ display:flex; flex-direction:column; align-items:flex-end; gap:12px; }
.footer-cta-right small{ font:600 10px/1 var(--mono); letter-spacing:.2em; color:var(--faint); text-transform:uppercase; }
.footer-grid{
  display:grid; grid-template-columns:1.5fr 1fr 1.1fr 1.1fr; gap:44px;
  padding:56px 0 20px;
}
.footer-brand p{ color:var(--muted); font-size:14px; max-width:270px; margin-top:16px; }
.footer-status{
  display:inline-flex; align-items:center; gap:9px; margin-top:22px;
  font:600 10px/1 var(--mono); letter-spacing:.2em; color:var(--cyan); text-transform:uppercase;
}
.footer-status .dot{ width:7px; height:7px; border-radius:50%; background:var(--cyan); box-shadow:0 0 10px rgba(58,232,255,.8); animation:blink 2.4s steps(1) infinite; }
.footer-col h4{ font:700 10.5px/1 var(--mono); letter-spacing:.24em; color:var(--faint); text-transform:uppercase; margin-bottom:20px; }
.footer-col ul{ display:grid; gap:12px; }
.footer-col a{ font-size:14px; color:var(--muted); transition:color .2s ease; }
.footer-col a:hover{ color:var(--amber-hi); }
.station{ display:flex; gap:12px; align-items:flex-start; }
.station + .station{ margin-top:18px; }
.station-code{
  flex:none; font:700 10px/1 var(--mono); letter-spacing:.1em; padding:6px 8px; border-radius:6px; margin-top:2px;
}
.station-code.md{ color:var(--amber); border:1px solid rgba(255,180,84,.4); background:rgba(255,180,84,.07); }
.station-code.lc{ color:var(--cyan); border:1px solid rgba(58,232,255,.4); background:rgba(58,232,255,.07); }
.station b{ display:block; font:600 14px/1.3 var(--sans); }
.station span{ font-size:12.5px; color:var(--faint); }
.footer-col .plain li{ font-size:14px; color:var(--muted); }
.footer-col .plain small{ display:block; color:var(--faint); font-size:12px; }
.footer-rail{ position:relative; height:44px; margin-top:26px; }
.footer-rail::before{
  content:""; position:absolute; left:0; right:0; top:50%; height:1px;
  background:repeating-linear-gradient(90deg, var(--line-2) 0 9px, transparent 9px 16px);
}
.footer-train{ position:absolute; top:50%; margin-top:-11px; left:-70px; animation:trainloop 30s linear infinite; }
.footer-bottom{
  display:flex; align-items:center; justify-content:space-between; gap:14px; flex-wrap:wrap;
  padding:22px 0 30px; border-top:1px solid var(--line);
  font:500 10px/1.7 var(--mono); letter-spacing:.16em; color:var(--faint); text-transform:uppercase;
}
.footer-bottom a{ color:var(--muted); } .footer-bottom a:hover{ color:var(--amber-hi); }

/* ============================================================
   Toast
   ============================================================ */
.toast{
  position:fixed; left:50%; bottom:26px; z-index:300;
  transform:translate(-50%, 16px); opacity:0; pointer-events:none;
  display:flex; align-items:center; gap:12px;
  background:#1e1546; border:1px solid rgba(255,180,84,.45); border-radius:12px;
  padding:14px 20px; max-width:min(480px, calc(100vw - 40px));
  box-shadow:0 20px 50px rgba(5,3,16,.6), 0 0 30px rgba(255,180,84,.1);
  font-size:13.5px; line-height:1.5; color:var(--cream);
  transition:transform .35s cubic-bezier(.2,.7,.2,1), opacity .35s ease;
}
.toast.show{ transform:translate(-50%,0); opacity:1; }
.toast svg{ flex:none; }

/* ============================================================
   Reveal on scroll
   ============================================================ */
.js .reveal{ opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s cubic-bezier(.2,.7,.2,1); }
.js .reveal.in{ opacity:1; transform:none; }

/* ============================================================
   Scene animations
   ============================================================ */
.tw{ animation:twinkle 4s ease-in-out infinite; }
.wflick{ animation:wflick 8s steps(1) infinite; }
.neonflick{ animation:neonflick 6s steps(1) infinite; }
.blinker{ animation:blink 2s steps(1) infinite; }
.beam{ animation:beamPulse 5s ease-in-out infinite; }
.train-ride{ animation:ride 3.2s ease-in-out infinite alternate; }
.shoot{ animation:shoot 12s linear infinite; animation-delay:4s; opacity:0; }
@keyframes twinkle{ 0%,100%{opacity:.25} 50%{opacity:1} }
@keyframes wflick{ 0%,91%{opacity:1} 92%,94%{opacity:.15} 95%,100%{opacity:1} }
@keyframes neonflick{ 0%,78%{opacity:1} 79%,81%{opacity:.25} 82%,88%{opacity:1} 89%{opacity:.4} 90%,100%{opacity:1} }
@keyframes blink{ 0%,60%{opacity:1} 61%,100%{opacity:.15} }
@keyframes ping{ 0%{transform:scale(.6);opacity:.9} 100%{transform:scale(2.1);opacity:0} }
@keyframes beamPulse{ 0%,100%{opacity:.22} 50%{opacity:.42} }
@keyframes ride{ from{transform:translateY(0)} to{transform:translateY(-1.4px)} }
@keyframes shoot{
  0%{ transform:translate(260px,235px); opacity:0; }
  2%{ opacity:.9; }
  9%{ transform:translate(640px,345px); opacity:0; }
  100%{ transform:translate(640px,345px); opacity:0; }
}
@keyframes tickmove{ from{transform:translateX(0)} to{transform:translateX(-50%)} }
@keyframes routedot{
  0%{ left:0; opacity:0; } 6%{ opacity:1; } 94%{ opacity:1; }
  100%{ left:calc(100% - 9px); opacity:0; }
}
@keyframes bump{ from{ opacity:0; transform:translateY(9px); } to{ opacity:1; transform:none; } }
@keyframes trainloop{
  0%{ left:-70px; opacity:0; } 4%{ opacity:1; } 96%{ opacity:1; } 100%{ left:100%; opacity:0; }
}

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width:1100px){
  .nav-chip{ display:none; }
  .board-cols, .t-row{ grid-template-columns:80px 80px minmax(0,1fr) 84px 138px 110px; gap:14px; }
}
@media (max-width:960px){
  .nav-links{ display:none; }
  .menu-btn{ display:block; }
  .mobile-menu{ display:block; }
  .section{ padding:88px 0; }
  .section-head{ flex-direction:column; align-items:flex-start; gap:20px; margin-bottom:44px; }
  .fare-grid{ grid-template-columns:1fr; max-width:470px; margin-inline:auto; }
  .fare-wrap.featured{ margin-top:6px; }
  .fare-head-right{ align-items:flex-start; }
  .footer-grid{ grid-template-columns:1fr 1fr; }
  .footer-cta{ flex-direction:column; align-items:flex-start; gap:28px; padding:60px 0 52px; }
  .footer-cta-right{ align-items:flex-start; }
}
@media (max-width:880px){
  .f-grid{ grid-template-columns:1fr; max-width:520px; }
  .board-cols{ display:none; }
  .t-row{
    grid-template-columns:1fr 1fr; gap:16px 20px; padding:22px 24px;
    grid-template-areas:"svc svc" "dep arr" "st fare";
  }
  .t-svc{ grid-area:svc; } .t-dep{ grid-area:dep; } .t-arr{ grid-area:arr; }
  .t-status{ grid-area:st; align-self:center; } .t-fare{ grid-area:fare; }
  .t-dur{ display:none; }
  .t-svc-tags .dur-m{ display:inline; }
  .t-dep::before, .t-arr::before{
    display:block; font:600 9px/1 var(--mono); letter-spacing:.22em; color:var(--faint); margin-bottom:7px;
  }
  .t-dep::before{ content:"DEPARTS"; } .t-arr::before{ content:"ARRIVES"; }
}
@media (max-width:720px){
  .hero{ min-height:0; padding-top:calc(var(--nav-h) + 52px); }
  .hero::before{ background:linear-gradient(180deg, rgba(15,11,34,.78), rgba(15,11,34,.6) 45%, rgba(15,11,34,.28)); }
  .hero h1{ font-size:clamp(38px, 10.5vw, 54px); }
  .hero-sub{ font-size:15.5px; }
  .route-strip{ padding-top:40px; }
  .route-strip-inner{ grid-template-columns:1fr; gap:22px; padding:20px 22px; }
  .rs-count{ text-align:left; display:flex; align-items:baseline; gap:14px; }
  .rs-count .rs-label{ margin:0; }
  .quote-mark{ left:-6px; top:-38px; transform:scale(.7); transform-origin:top left; }
  .quote-stub{ margin-left:0; }
}
@media (max-width:560px){
  .container{ width:calc(100% - 36px); }
  .footer-grid{ grid-template-columns:1fr; gap:36px; }
  .hero-ctas .btn{ flex:1; justify-content:center; }
  .board-bar{ padding:16px 20px; }
  .t-row{ padding:20px; }
  .board-note{ padding:14px 20px; }
  .footer-bottom{ flex-direction:column; align-items:flex-start; }
}

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce){
  *,*::before,*::after{ animation:none !important; transition:none !important; }
  .shoot,.rs-dot{ display:none; }
  .js .reveal{ opacity:1; transform:none; }
}
